\title{Sharp Lower Bounds for Sumsets in $L_1$ Balls in $\mathbb{Z}^d$}
\author{Aristotle}
\date{2026-07-13}

\begin{document}
\maketitle

\begin{abstract}
We study lower bounds for the cardinality of iterated sumsets
$A_1 + \cdots + A_n$ where each $A_j$ is a finite nonempty subset of the discrete
$L_1$ ball (cross-polytope) $\Bd(m) = \{x \in \Z^d : \sum_i |x_i| \le m\}$.
We establish three interlocking lower bounds and one containment bound, and we
identify the sharp exponent governing the extremal case. Our additive engine is an
iterated Cauchy--Davenport inequality valid in any torsion-free abelian group:
$\sum_j |A_j| + 1 \le |A_1 + \cdots + A_n| + n$. From it we derive the
multiplicative form $\prod_j |A_j| \le |A_1 + \cdots + A_n|^n$ and its
geometric-mean consequence $(\prod_j |A_j|)^{1/n} \le |A_1 + \cdots + A_n|$. On the
geometric side, the $L_1$ triangle inequality yields $A_1 + \cdots + A_n \subseteq
\Bd(nm)$. We introduce the transcendental exponent $p = n\log(m+1)/\log(nm+1)$,
prove that $1 \le p \le n$, and prove the identity $(m+1)^{n/p} = nm+1$. We show
that in dimension one the configuration $A_j = \{0,1,\ldots,m\}$ attains equality
simultaneously in the additive bound and in the geometric bound with exponent $p$,
so $p$ cannot be replaced by any smaller value. These results bridge additive
combinatorics, discrete convex geometry, and the analysis of a single sharp
transcendental constant.
\end{abstract}

\section{Introduction}

A recurring theme in additive combinatorics is that the sumset of two sets is never
much smaller than its constituents. In a torsion-free abelian group the statement
$|A + B| \ge |A| + |B| - 1$ holds for nonempty finite sets, with equality precisely
for arithmetic progressions of a common difference.

Fix a dimension $d \ge 1$ and radius $m \ge 0$. The \emph{discrete $L_1$ ball}
(lattice cross-polytope) of radius $m$ is
\[
  \Bd(m) = \Bigl\{x \in \Z^d : \sum_{i=1}^d |x_i| \le m\Bigr\}.
\]
Given $n$ finite nonempty $A_1, \ldots, A_n \subseteq \Bd(m)$, we ask how small the
iterated sumset $A_1 + \cdots + A_n = \{a_1 + \cdots + a_n : a_j \in A_j\}$ can be,
in terms of $|A_1|, \ldots, |A_n|$, the radius $m$, and $n$. The target is a bound
\[
  |A_1 + \cdots + A_n| \ge \bigl(|A_1| \cdots |A_n|\bigr)^{1/p}
\]
with $p$ as small as possible; smaller $p$ is a stronger conclusion.

Our contributions: an iterated Cauchy--Davenport bound (Theorem~\ref{thm:icd}); its
multiplicative (Theorem~\ref{thm:mult}) and geometric-mean (Theorem~\ref{thm:gm})
forms; a containment bound (Theorem~\ref{thm:contain}); the sharp exponent
$p = n\log(m+1)/\log(nm+1)$ with range $1 \le p \le n$ (Theorems~\ref{thm:pupper},
\ref{thm:plower}) and identity $(m+1)^{n/p} = nm+1$ (Theorem~\ref{thm:pid}); an
extremal sharpness result (Theorem~\ref{thm:extremal}); and a packaged bridge
theorem (Theorem~\ref{thm:bridge}).

\section{Preliminaries}

We work with finite subsets of a fixed abelian group $G$. A group is
\emph{torsion-free} if $kx = 0$ with $k \ge 1$ forces $x = 0$; the lattice $\Z^d$ is
torsion-free. For finite $A, B \subseteq G$, $A + B = \{a + b : a \in A, b \in B\}$,
and iterated sums $\sum_{i \in s} A_i$ over a finite index set $s$ are well defined
by commutativity and associativity.

\begin{lemma}[Nonemptiness]\label{lem:ne}
If $s$ is nonempty and each $A_i$ is nonempty for $i \in s$, then
$\sum_{i \in s} A_i$ is nonempty.
\end{lemma}
\begin{proof}[Proof sketch]
Induct on $s$; a pointwise sum of nonempty sets is nonempty.
\end{proof}

\section{The additive engine}

The single-step bound in a torsion-free abelian group states that for nonempty
finite $A, B$,
\begin{equation}\label{eq:cd}
  |A + B| \ge |A| + |B| - 1.
\end{equation}
Intuitively, embedding $G$ into an ordered group, the sums
$a_1 + b_1 < a_1 + b_2 < \cdots < a_1 + b_{|B|} < a_2 + b_{|B|} < \cdots$ give
$|A| + |B| - 1$ distinct values.

\begin{theorem}[Iterated Cauchy--Davenport]\label{thm:icd}
Let $G$ be a torsion-free abelian group, $s$ a nonempty finite index set, and
$A_i \subseteq G$ nonempty finite for $i \in s$. Then
\[
  \sum_{i \in s} |A_i| + 1 \le \Bigl|\sum_{i \in s} A_i\Bigr| + |s|,
\]
equivalently $\bigl|\sum_{i \in s} A_i\bigr| \ge \sum_{i \in s} |A_i| - (|s| - 1)$.
\end{theorem}
\begin{proof}[Proof sketch]
Induct on $s$. The base case $|s|=1$ is trivial. For $s = \{a\} \cup s'$ with
$a \notin s'$, let $S' = \sum_{i \in s'} A_i$ (nonempty by Lemma~\ref{lem:ne}).
Applying \eqref{eq:cd} to $A_a$ and $S'$ and the inductive hypothesis to $s'$ gives
the result after elementary arithmetic using $|s| = |s'| + 1$.
\end{proof}

\section{The multiplicative form}

\begin{lemma}[Each factor embeds]\label{lem:embed}
Under the hypotheses of Theorem~\ref{thm:icd}, for every $j \in s$,
$|A_j| \le \bigl|\sum_{i \in s} A_i\bigr|$.
\end{lemma}
\begin{proof}[Proof sketch]
Write $\sum_{i \in s} A_i = A_j + \sum_{i \in s \setminus \{j\}} A_i$; adding a
nonempty set only enlarges cardinality since translation is injective.
\end{proof}

\begin{theorem}[Multiplicative bound]\label{thm:mult}
Under the hypotheses of Theorem~\ref{thm:icd},
$\prod_{i \in s} |A_i| \le \bigl|\sum_{i \in s} A_i\bigr|^{\,|s|}$.
\end{theorem}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:embed} each $|A_i| \le C := |\sum_i A_i|$; multiply the $|s|$
inequalities.
\end{proof}

\section{The geometric-mean form}

\begin{lemma}[Root monotonicity]\label{lem:root}
For $P, C \in \Z_{\ge 0}$ and $n \ge 1$, if $P \le C^n$ then $P^{1/n} \le C$.
\end{lemma}
\begin{proof}[Proof sketch]
Write $C = (C^n)^{1/n}$ and apply monotonicity of $t \mapsto t^{1/n}$.
\end{proof}

\begin{theorem}[Geometric-mean bound; $p=n$ case]\label{thm:gm}
Under the hypotheses of Theorem~\ref{thm:icd} with $n = |s|$,
\[
  \Bigl(\prod_{i \in s} |A_i|\Bigr)^{1/n} \le \Bigl|\sum_{i \in s} A_i\Bigr|.
\]
\end{theorem}
\begin{proof}
Combine Theorem~\ref{thm:mult} with Lemma~\ref{lem:root}.
\end{proof}

This is the target inequality with exponent $p = n$, valid for arbitrary finite
nonempty sets in any torsion-free abelian group.

\section{Worked examples}

\begin{example}[Two intervals]
For $A = \{0,1,2\}$, $B = \{0,10,20\}$ in $\Z$, all nine sums are distinct, so
$|A+B| = 9$, far above the floor $|A|+|B|-1 = 5$. But $A+A = \{0,1,2,3,4\}$ has
$|A+A| = 5 = |A|+|A|-1$: the additive bound is tight exactly for arithmetic
progressions.
\end{example}

\begin{example}[Confinement helps]
For $n=3$, $m=5$ the geometric-mean exponent is $3$ while
$p(3,5) = 3\log 6/\log 16 \approx 1.938$. For $A_j = \{0,\ldots,5\}$,
$\prod_j|A_j| = 216$ and $|\sum_j A_j| = 16$: the geometric-mean bound gives
$216^{1/3} = 6 \le 16$ (loose), the sharp bound gives $216^{1/1.938} = 16 \le 16$
(equality).
\end{example}

\begin{example}[Planar sumset]
In $d=2$, $m=2$, $|B_2(2)| = 13$ and $A + A \subseteq B_2(4)$ with
$|B_2(4)| = 41$; taking $A = B_2(2)$ gives $|A+A| = 41$, saturating the
containment, while $13^2 \le 41^2$ holds for the multiplicative bound.
\end{example}

\section{Discrete geometry: $L_1$ balls}

\begin{definition}[$L_1$ norm and ball]
For $x \in \Z^d$, $\|x\|_1 = \sum_{i=1}^d |x_i|$, and
$\Bd(m) = \{x \in \Z^d : \|x\|_1 \le m\}$.
\end{definition}

\begin{lemma}[Triangle inequality]\label{lem:tri}
For $x, y \in \Z^d$, $\|x + y\|_1 \le \|x\|_1 + \|y\|_1$.
\end{lemma}
\begin{proof}[Proof sketch]
Sum the coordinatewise inequalities $|x_i + y_i| \le |x_i| + |y_i|$.
\end{proof}

\begin{theorem}[Containment / geometry bridge]\label{thm:contain}
If $A_i \subseteq \Bd(m)$ for each $i \in s$, then
$\sum_{i \in s} A_i \subseteq \Bd(|s| \cdot m)$.
\end{theorem}
\begin{proof}[Proof sketch]
Induct on $s$: if $B \subseteq \Bd(p)$ and $C \subseteq \Bd(q)$ then
$B + C \subseteq \Bd(p+q)$ by Lemma~\ref{lem:tri}. Accumulate radii over $|s|$
summands of radius $m$.
\end{proof}

\section{The sharp transcendental exponent}

\begin{definition}[Sharp exponent]
For integers $n, m \ge 1$,
$p = p(n,m) = \dfrac{n \, \log(m+1)}{\log(nm+1)}$.
\end{definition}

\begin{theorem}[Defining identity]\label{thm:pid}
For $n, m \ge 1$, $(m+1)^{n/p} = nm + 1$.
\end{theorem}
\begin{proof}[Proof sketch]
Since $\log(m+1), \log(nm+1) > 0$, $n/p = \log(nm+1)/\log(m+1)$, so
$(m+1)^{n/p} = \exp(\log(nm+1)) = nm+1$.
\end{proof}

\begin{theorem}[Upper range]\label{thm:pupper}
For $n, m \ge 1$, $p(n,m) \le n$.
\end{theorem}
\begin{proof}[Proof sketch]
Equivalent to $\log(m+1) \le \log(nm+1)$, true since $m+1 \le nm+1$.
\end{proof}

\begin{theorem}[Lower range]\label{thm:plower}
For $n, m \ge 1$, $1 \le p(n,m)$.
\end{theorem}
\begin{proof}[Proof sketch]
Equivalent to $nm + 1 \le (m+1)^n$, the Bernoulli inequality $(1+m)^n \ge 1 + nm$.
\end{proof}

Thus $1 \le p \le n$: confinement to the ball drives $p$ below $n$ but never past
the floor $p = 1$.

\section{Extremal sharpness in dimension one}

Here $B_1(m) = \{-m, \ldots, m\}$.

\begin{lemma}[Sum of intervals]\label{lem:iccadd}
For integers $a \le b$, $c \le d$,
$\{a, \ldots, b\} + \{c, \ldots, d\} = \{a+c, \ldots, b+d\}$.
\end{lemma}

\begin{lemma}[$n$-fold interval]\label{lem:nfold}
For $m \ge 0$, the $n$-fold sum of $\{0, \ldots, m\}$ is $\{0, \ldots, nm\}$, of
cardinality $nm + 1$.
\end{lemma}
\begin{proof}[Proof sketch]
Induct using Lemma~\ref{lem:iccadd}.
\end{proof}

\begin{theorem}[Extremal sharpness]\label{thm:extremal}
Fix $n, m \ge 1$ and take $A_1 = \cdots = A_n = \{0, 1, \ldots, m\} \subseteq
B_1(m)$. Then
\begin{enumerate}
  \item $\sum_j |A_j| + 1 = |\sum_j A_j| + n$ (additive equality);
  \item $\bigl(\prod_j |A_j|\bigr)^{1/p} = |\sum_j A_j|$ with $p = p(n,m)$.
\end{enumerate}
Consequently $p$ is optimal: no exponent smaller than $p$ satisfies
$\bigl(\prod_j |A_j|\bigr)^{1/p} \le |\sum_j A_j|$ for all admissible configurations.
\end{theorem}
\begin{proof}[Proof sketch]
Each $|A_j| = m+1$, so $\sum_j |A_j| = n(m+1)$ and $\prod_j |A_j| = (m+1)^n$. By
Lemma~\ref{lem:nfold}, $\sum_j A_j = \{0, \ldots, nm\}$, so $|\sum_j A_j| = nm+1$.
For (1): $n(m+1)+1 = (nm+1) + n$. For (2): $((m+1)^n)^{1/p} = (m+1)^{n/p} = nm+1$ by
Theorem~\ref{thm:pid}. For optimality, any $p' < p$ gives $(m+1)^{n/p'} > nm+1$,
violating the bound.
\end{proof}

\section{The bridge theorem}

\begin{theorem}[$L_1$-ball sumset bridge]\label{thm:bridge}
Let $d \ge 1$, $m \ge 0$, and $A_i \subseteq \Bd(m)$ nonempty finite for $i$ in a
nonempty finite index set $s$, with $n = |s|$. Then simultaneously:
\begin{enumerate}
  \item $\sum_{i \in s} |A_i| + 1 \le \bigl|\sum_{i \in s} A_i\bigr| + n$;
  \item $\prod_{i \in s} |A_i| \le \bigl|\sum_{i \in s} A_i\bigr|^{n}$;
  \item $\bigl(\prod_{i \in s} |A_i|\bigr)^{1/n} \le \bigl|\sum_{i \in s} A_i\bigr|$;
  \item $\sum_{i \in s} A_i \subseteq \Bd(nm)$.
\end{enumerate}
\end{theorem}
\begin{proof}
Items (1)--(3) are Theorems~\ref{thm:icd}, \ref{thm:mult}, \ref{thm:gm}; item (4)
is Theorem~\ref{thm:contain}. All apply since $\Z^d$ is torsion-free.
\end{proof}

Together with Theorem~\ref{thm:extremal}, this connects additive combinatorics,
discrete convex geometry, and the transcendental exponent $p$.

\section{Applications and future work}

The cardinality of the cross-polytope is
$|\Bd(m)| = \sum_{k \ge 0} 2^k \binom{d}{k}\binom{m}{k}$ (a Delannoy-type count),
controlling the ambient room for the sets $A_j$. The $L_1$ ball is the canonical
sparsity model, so confined sumset bounds inform sparse recovery and lattice codes.

Open directions include: (1) the full sharp inequality
$|A_1 + \cdots + A_n| \ge (\prod_j |A_j|)^{1/p}$ with optimal $p$ for arbitrary
subsets of $\Bd(m)$ in all $d$, plausibly via a discrete Pr\'ekopa--Leindler /
Brunn--Minkowski inequality; (2) a compression/tensorization reducing arbitrary sets
to intervals dimension by dimension; (3) a $d$-dependent exponent
$p_d = n\log|\Bd(m)|/\log|\Bd(nm)|$; (4) equality characterization forcing
arithmetic progressions (Vosper/Freiman rigidity); and (5) analogues in $\R^d$ and
$(\Z/N\Z)^d$.

