"""Verify all four sumset bounds by brute-force enumeration in B_d(m)."""
from __future__ import annotations
import math
from itertools import product
from typing import Sequence, Set, Tuple

Point = Tuple[int, ...]

def l1_norm(x: Point) -> int:
    return sum(abs(c) for c in x)

def l1_ball(d: int, m: int) -> Set[Point]:
    return {x for x in product(*([range(-m, m + 1)] * d)) if l1_norm(x) <= m}

def sumset(sets: Sequence[Set[Point]]) -> Set[Point]:
    dim = len(next(iter(sets[0])))
    acc: Set[Point] = {tuple([0] * dim)}
    for A in sets:
        acc = {tuple(a + b for a, b in zip(x, y)) for x in acc for y in A}
    return acc

def check(sets: Sequence[Set[Point]], d: int, m: int) -> bool:
    n = len(sets)
    sizes = [len(A) for A in sets]
    S = sumset(sets); c = len(S)
    additive = sum(sizes) + 1 <= c + n
    multiplicative = math.prod(sizes) <= c ** n
    geometric = math.prod(sizes) ** (1.0 / n) <= c + 1e-9
    containment = all(l1_norm(x) <= n * m for x in S)
    return additive and multiplicative and geometric and containment

if __name__ == "__main__":
    ball = sorted(l1_ball(2, 3))
    sets = [set(ball[:5]), set(ball[3:10]), set(ball[:7])]
    print("all four bounds hold:", check(sets, d=2, m=3))

"""The sharp exponent p = n log(m+1)/log(nm+1): identity and range checks."""
from __future__ import annotations
import math

def sharp_exponent(n: int, m: int) -> float:
    return n * math.log(m + 1) / math.log(n * m + 1)

def report(n: int, m: int) -> None:
    p = sharp_exponent(n, m)
    identity = (m + 1) ** (n / p)           # should equal n*m + 1
    print(f"n={n} m={m}: p={p:.6f}  (m+1)^(n/p)={identity:.6f}  "
          f"nm+1={n*m+1}  1<=p<=n: {1.0 <= p <= n}")

if __name__ == "__main__":
    for n in (2, 3, 5, 8):
        for m in (1, 2, 5, 20):
            report(n, m)

"""Extremal interval A_j={0,...,m} in Z^1 saturates the sharp exponent bound."""
from __future__ import annotations
import math

def extremal_check(n: int, m: int) -> dict:
    # A_j = {0,...,m}: |A_j| = m+1, sumset = {0,...,nm}, |sumset| = nm+1.
    size = m + 1
    sumset_card = n * m + 1
    prod = size ** n
    p = n * math.log(m + 1) / math.log(n * m + 1)
    return {
        "additive_equality": n * size + 1 == sumset_card + n,
        "sharp_value": prod ** (1.0 / p),
        "sumset_card": sumset_card,
        "sharp_equality": abs(prod ** (1.0 / p) - sumset_card) < 1e-9,
    }

if __name__ == "__main__":
    for n in (2, 3, 4):
        for m in (1, 3, 7):
            print(f"n={n} m={m}: {extremal_check(n, m)}")

