"""Visualize how a sumset of two diamond subsets fills a larger diamond."""
import matplotlib.pyplot as plt

def l1_ball(m):
    return {(x, y) for x in range(-m, m + 1) for y in range(-m, m + 1)
            if abs(x) + abs(y) <= m}

m = 3
A = {(x, y) for (x, y) in l1_ball(m) if x >= 0 and y >= 0}
B = {(x, y) for (x, y) in l1_ball(m) if x <= 0}
S = {(ax + bx, ay + by) for (ax, ay) in A for (bx, by) in B}

fig, axes = plt.subplots(1, 3, figsize=(15, 5))
for ax, (pts, title) in zip(axes, [(A, "A in B_2(3)"),
                                   (B, "B in B_2(3)"),
                                   (S, f"A+B in B_2(6): {len(S)} pts")]):
    xs, ys = zip(*pts)
    ax.scatter(xs, ys, s=30, color="teal")
    ax.set_aspect("equal"); ax.grid(True, alpha=0.3); ax.set_title(title)
plt.suptitle("Sumset containment: A + B is trapped inside B_2(2*3)")
plt.tight_layout(); plt.savefig("sumset_growth.png", dpi=120)
print("saved sumset_growth.png")
